const item = $input.first();
const input = item.json || {};
const clean = (value) => typeof value === 'string' ? value.trim() : '';
const taskId = clean(input.task_id);
const action = clean(input.action).toLowerCase() || 'status';
const humanResponse = clean(input.human_response);
const requestedBy = clean(input.requested_by) || 'anonymous';
const allowed = new Set(['status', 'reply', 'approve', 'reject', 'cancel']);
const binary = item.binary && typeof item.binary === 'object' ? item.binary : null;
const binaryKeys = binary ? Object.keys(binary) : [];
if (!taskId) {
  return [{ json: { entrypoint: 'human_gate_form', input_valid: false, status: 'invalid', message: 'task_id is required.', form_action: action, human_response: humanResponse, requested_by: requestedBy, hitl_binary_keys: binaryKeys }, ...(binary ? { binary } : {}) }];
}
if (!allowed.has(action)) {
  return [{ json: { entrypoint: 'human_gate_form', input_valid: false, status: 'invalid', message: 'Unsupported action.', form_action: action, task_id: taskId, human_response: humanResponse, requested_by: requestedBy, hitl_binary_keys: binaryKeys }, ...(binary ? { binary } : {}) }];
}
return [{ json: {
  entrypoint: 'human_gate_form',
  action: 'status',
  task_id: taskId,
  requested_by: requestedBy,
  form_action: action,
  human_response: humanResponse,
  hitl_binary_keys: binaryKeys,
}, ...(binary ? { binary } : {}) }];

const prepared = $('Prepare status lookup').first().json || {};
const preparedItem = $('Prepare status lookup').first();
const statusResponse = $input.first().json || {};
const formAction = String(prepared.form_action || 'status').toLowerCase();
const humanResponse = String(prepared.human_response || '').trim();
const requestedBy = String(prepared.requested_by || 'anonymous').trim();
const gate = statusResponse.human_gate && typeof statusResponse.human_gate === 'object' ? statusResponse.human_gate : null;
const awaiting = statusResponse.status === 'awaiting_human' && gate && gate.gate_id;
const mutating = ['reply', 'approve', 'reject', 'cancel'].includes(formAction);
const binary = preparedItem.binary && typeof preparedItem.binary === 'object' ? preparedItem.binary : null;
const binaryKeys = binary ? Object.keys(binary) : (Array.isArray(prepared.hitl_binary_keys) ? prepared.hitl_binary_keys : []);
let shouldResume = false;
let blockReason = '';
if (prepared.input_valid === false) {
  blockReason = prepared.message || 'Invalid form input.';
} else if (!mutating) {
  blockReason = 'status_only';
} else if (!awaiting) {
  blockReason = statusResponse.status === 'not_found'
    ? 'Task not found. Check Task ID.'
    : `Task status is ${statusResponse.status || 'unknown'}; there is no open human_gate to answer.`;
} else if (formAction === 'reply' && !humanResponse && !binaryKeys.length) {
  blockReason = 'human_response is required for reply (or attach HITL files with a short reply).';
} else if (!requestedBy || requestedBy === 'anonymous') {
  blockReason = 'requested_by must be a named accountable engineering identity.';
} else {
  shouldResume = true;
}
const expectedVersion = Number(gate?.expected_version ?? statusResponse.version);
if (shouldResume && (!Number.isInteger(expectedVersion) || expectedVersion < 1 || !gate?.gate_id)) {
  shouldResume = false;
  blockReason = 'Open human_gate is missing integer expected_version or gate_id; reload status or re-open the gate.';
}
const effectiveResponse = humanResponse || (binaryKeys.length ? JSON.stringify({text:'Attached HITL files for new-well definitions.',hitl_files:binaryKeys}) : '');
const resumePayload = shouldResume ? {
  entrypoint: 'human_gate_form',
  action: formAction,
  task_id: statusResponse.task_id || prepared.task_id,
  expected_version: expectedVersion,
  gate_id: String(gate.gate_id),
  human_response: effectiveResponse,
  requested_by: requestedBy,
  hitl_binary_keys: binaryKeys,
} : null;
return [{ json: {
  should_resume: shouldResume,
  block_reason: blockReason,
  form_action: formAction,
  human_response: effectiveResponse,
  requested_by: requestedBy,
  status_response: statusResponse,
  human_gate: gate,
  resume_payload: resumePayload,
  hitl_binary_keys: binaryKeys,
  ...(resumePayload || {}),
}, ...(binary ? { binary } : {}) }];

const decisionItem = $('Decide resume from status').first();
const decision = decisionItem.json || {};
const payload = decision.resume_payload && typeof decision.resume_payload === 'object' ? decision.resume_payload : {};
const binary = decisionItem.binary && typeof decisionItem.binary === 'object' ? decisionItem.binary : null;
return [{ json: { ...payload }, ...(binary ? { binary } : {}) }];

const decision = $('Decide resume from status').first().json || {};
const resumed = $json && typeof $json === 'object' ? $json : {};
const usedResume = Boolean(decision.should_resume);
const response = usedResume ? resumed : (decision.status_response || {});
const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const prettyJson = (value, limit = 16000) => {
  let text;
  try { text = JSON.stringify(value, null, 2); } catch { text = String(value); }
  return text.length > limit ? `${text.slice(0, limit)}\n… truncated for display` : text;
};
const questionText = (q) => {
  if (!q || typeof q !== 'object') return String(q ?? '');
  return String(q.text || q.question || q.message || q.id || '').trim();
};
const gate = response.human_gate && typeof response.human_gate === 'object'
  ? response.human_gate
  : (decision.human_gate || null);
const questions = Array.isArray(gate?.questions) ? gate.questions : [];
const status = String(response.status || decision.block_reason || 'error');
const taskId = String(response.task_id || decision.resume_payload?.task_id || decision.status_response?.task_id || '');
const version = response.version ?? decision.status_response?.version ?? null;
const message = String(response.message || decision.block_reason || 'Request processed.');
const questionItems = questions
  .map((q, index) => `<li><strong>${escapeHtml(String(q.id || `q${index + 1}`))}</strong>: ${escapeHtml(questionText(q))}${q.expected_format ? ` <em>(format: ${escapeHtml(q.expected_format)})</em>` : ''}</li>`)
  .join('');
const result = response.result && typeof response.result === 'object' ? response.result : null;
const deliverables = Array.isArray(result?.deliverables) ? result.deliverables : [];
const scheduleText = response.schedule_text
  || result?.release?.schedule_text
  || result?.compact_data?.generated_schedule
  || deliverables.find((value) => typeof value?.schedule_text === 'string')?.schedule_text
  || null;
const autoCas = usedResume
  ? `<p><strong>CAS fields applied automatically:</strong> expected_version=<code>${escapeHtml(decision.resume_payload?.expected_version)}</code>, gate_id=<code>${escapeHtml(decision.resume_payload?.gate_id)}</code></p>`
  : '';
const inspectHint = !usedResume && gate
  ? `<section>
<h2>Open human gate</h2>
<p><strong>Why the orchestrator is waiting:</strong> ${escapeHtml(gate.reason || message)}</p>
<p><strong>Gate kind:</strong> <code>${escapeHtml(gate.kind || '')}</code></p>
${questionItems ? `<p><strong>Answer these points:</strong></p><ol>${questionItems}</ol>` : ''}
<p>Submit this form again with the same Task ID, action <code>reply</code>/<code>approve</code>/<code>reject</code>, and your answer. Version/gate_id stay automatic.</p>
</section>`
  : '';
const nextGate = usedResume && gate
  ? `<section>
<h2>Still waiting / next gate</h2>
<p>${escapeHtml(gate.reason || message)}</p>
${questionItems ? `<ol>${questionItems}</ol>` : ''}
</section>`
  : '';
const blocked = !usedResume && decision.block_reason && decision.block_reason !== 'status_only'
  ? `<p><strong>Could not resume:</strong> ${escapeHtml(decision.block_reason)}</p>`
  : '';
const scheduleBlock = scheduleText
  ? `<section><h2>schedule.inc</h2><pre>${escapeHtml(String(scheduleText).slice(0, 100000))}</pre></section>`
  : '';
const html = `<main>
<h1>MAS human gate</h1>
<p>Status: <strong>${escapeHtml(status)}</strong></p>
<p>${escapeHtml(message)}</p>
<p>Task ID: <code>${escapeHtml(taskId || 'n/a')}</code></p>
<p>Version: <code>${escapeHtml(version ?? 'n/a')}</code></p>
<p>Requested action: <code>${escapeHtml(decision.form_action || '')}</code></p>
${autoCas}
${blocked}
${inspectHint}
${nextGate}
${scheduleBlock}
<details><summary>Structured response</summary><pre>${escapeHtml(prettyJson({ status_response: decision.status_response, resume_response: usedResume ? response : null, decision: { should_resume: decision.should_resume, block_reason: decision.block_reason, form_action: decision.form_action } }))}</pre></details>
</main>`;
return [{ json: { ...response, form_response_html: html, human_gate: gate } }];
